export function historyFor(style: Style): string {
  if (style.region === "invented") {
    return `An original speculative look created for this atlas, rather than a documented historical movement. Its creative premise: ${style.summary} Its visual ingredients include ${style.look.charAt(0).toLowerCase()}${style.look.slice(1)}`;
  }
  const note = NOTES[style.id];
  if (!note) throw new Error(`Missing history for ${style.id}`);
  return note;
}

